const request = require('request');

const options = {
  method: 'GET',
  url: 'http://localhost:8080/rest/v2.0/companies/1234/assets/%7Bentity_type%7D/%7Bentity_id%7D/history',
  qs: {
    'filters[change_type]': 'SOME_STRING_VALUE',
    'filters[changed_by]': 'SOME_STRING_VALUE',
    'filters[changed_at]': 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  },
  headers: {
    'Procore-Company-Id': 'SOME_INTEGER_VALUE',
    'Accept-Language': 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("http://localhost:8080/rest/v2.0/companies/1234/assets/%7Bentity_type%7D/%7Bentity_id%7D/history?filters%5Bchange_type%5D=SOME_STRING_VALUE&filters%5Bchanged_by%5D=SOME_STRING_VALUE&filters%5Bchanged_at%5D=SOME_STRING_VALUE&sort=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_INTEGER_VALUE" },
        { "Accept-Language", "SOME_STRING_VALUE" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

